import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { resolve } from 'node:path';
import { buildTulipAssessments } from './lib/build-tulip-assessments.mjs';

const root = fileURLToPath(new URL('../', import.meta.url));
const registry = await buildTulipAssessments(root);
const json = `${JSON.stringify(registry, null, 2)}\n`;
const outputs = {
  'public/tulip-assessments.json': json,
  'src/tulip-assessment-registry.js': `// Generated by npm run export:tulip-assessments. Do not edit.\nexport default ${JSON.stringify(registry)};\n`,
};
for (const [path, content] of Object.entries(outputs)) {
  if (process.argv.includes('--check')) {
    if (await readFile(resolve(root, path), 'utf8') !== content) throw new Error(`Stale assessment export: ${path}`);
  } else {
    await writeFile(resolve(root, path), content);
  }
}
const records = Object.values(registry.records);
console.log(`Shared assessments: ${records.length} nodes; ${registry.coverage.assessed} scored, ${registry.coverage.unscored} not yet scored, ${registry.coverage.responses} responses. ${registry.revision}`);
